[CmdletBinding()]
param([Parameter(Mandatory)][string] $RepositoryRoot, [switch] $SkipBuild)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
$repository = (Resolve-Path -LiteralPath $RepositoryRoot).Path
Push-Location $repository
try {
    if (-not $SkipBuild) {
        dotnet build src/Grace.Server/Grace.Server.fsproj --configuration Release --nologo -p:CopyLocalLockFileAssemblies=true
        if ($LASTEXITCODE -ne 0) { throw 'The matching Release build failed.' }
    }
    $binaryDirectory = Join-Path $repository 'src/Grace.Server/bin/Release/net10.0'
    $references = [Collections.Generic.List[string]]::new()
    $references.Add('#I "' + $binaryDirectory.Replace('\', '/') + '"')
    foreach ($file in Get-ChildItem -LiteralPath $binaryDirectory -Filter '*.dll' | Sort-Object Name) {
        if ($file.Name -eq 'FSharp.Core.dll') { continue }
        try { [void][Reflection.AssemblyName]::GetAssemblyName($file.FullName) }
        catch { continue }
        $references.Add('#r "' + $file.Name + '"')
    }
    # The loader contains references only; Wire.fsx owns execution and cannot trigger provider experiments.
    [IO.File]::WriteAllLines((Join-Path $PSScriptRoot 'Load.fsx'), $references, [Text.UTF8Encoding]::new($false))
    dotnet fsi (Join-Path $PSScriptRoot 'Wire.fsx')
    if ($LASTEXITCODE -ne 0) { throw 'The serializer controls failed.' }
}
finally { Pop-Location }

